import{_ as e,a as r,c as l,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Lua 宿主排错：加载、回调、内存与关闭边界","description":"按阶段区分 Lua C 宿主的栈失衡、非字符串错误、引用泄漏、链接配置与内存预算问题，给出可检查的诊断路径。","frontmatter":{"title":"Lua 宿主排错：加载、回调、内存与关闭边界","description":"按阶段区分 Lua C 宿主的栈失衡、非字符串错误、引用泄漏、链接配置与内存预算问题，给出可检查的诊断路径。","showdocs":{"topics":[{"id":"lua","title":"Lua","link":"/topics/lua/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"LuaHost：C API、所有权与可信插件","summary":"按阶段区分 Lua C 宿主的栈失衡、非字符串错误、引用泄漏、链接配置与内存预算问题，给出可检查的诊断路径。","status":"active","related":[{"title":"Lua 5.4 C API：栈、值转换与保护调用","link":"/programming/lua/plus/subjects/host-api","kind":"知识专题","scope":"general","audience":"general"},{"title":"Lua 首批课程：table、闭包、模块与日志统计","link":"/programming/lua/base/basic/foundations","kind":"知识专题","scope":"general","audience":"general"},{"title":"Lua 宿主所有权：registry、userdata 与状态关闭","link":"/programming/lua/plus/subjects/host-ownership","kind":"知识专题","scope":"general","audience":"general"},{"title":"Lua 元表、协程调度协议与宿主边界","link":"/programming/lua/base/advanced/protocol-host","kind":"知识专题","scope":"general","audience":"general"},{"title":"Lua C 宿主完整实践：受信任计数器插件","link":"/programming/lua/plus/practice/host-application","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"Lua C 宿主完整实践：受信任计数器插件 · 确定性验收规格至参考解答","link":"/programming/lua/plus/practice/host-application-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Lua C 宿主完整实践：受信任计数器插件 · 确定性验收规格至参考解答","link":"/programming/lua/plus/practice/host-application-part-02"},"next":false},"headers":[],"relativePath":"programming/lua/plus/troubleshooting/host-diagnostics.md","filePath":"programming/lua/plus/troubleshooting/host-diagnostics.md"}'),o={name:"programming/lua/plus/troubleshooting/host-diagnostics.md"};function i(n,a,s,u,c,p){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="lua-宿主排错-加载、回调、内存与关闭边界" tabindex="-1">Lua 宿主排错：加载、回调、内存与关闭边界 <a class="header-anchor" href="#lua-宿主排错-加载、回调、内存与关闭边界" aria-label="Permalink to &quot;Lua 宿主排错：加载、回调、内存与关闭边界&quot;">​</a></h1><p>前置为<a href="/programming/lua/plus/practice/host-application#inputs">完整工程</a>。示例未执行；排查步骤是后续运行时的检查顺序，错误文字仅是预期。不要先通过扩大权限、打开全部标准库或忽略类型校验消除报错，应先确认失败属于哪个边界。</p><h2 id="phases" tabindex="-1">按阶段识别错误 <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;按阶段识别错误 {#phases}&quot;">​</a></h2><p>Lua宿主加载成功却不能执行怎么排查？区分 load、chunk、contract、callback 和 result 阶段。load 失败通常是文件、文本编译或模式不匹配；chunk 成功只说明顶层代码完成，还需检查它返回函数；callback 才是业务函数执行；result 则检查返回值是否符合宿主协议。</p><p>本例保留 Request.phase，主程序输出 <code>error[阶段]</code>；这比只检查错误字符串更稳定。not-function.lua 应到 contract，wrong-result.lua 到 result，syntax-error.lua 在 load；若把它们都叫“Lua 脚本错误”，读者无法判断修文件路径还是修函数接口。保护调用非零状态下不能继续把栈顶当成功返回值解析。</p><p>若 <code>attempt to call a nil value</code> 指向 missing_capability，这是故意未提供的能力或脚本拼写错误。当前状态没有打开标准库，所以 print 和 require 也不存在；需求确实需要时应逐项设计导出，而不是调用 luaL_openlibs 后仍保留“只有两个计数器方法”的能力描述。</p><h2 id="error-object" tabindex="-1">错误对象与 traceback <a class="header-anchor" href="#error-object" aria-label="Permalink to &quot;错误对象与 traceback {#error-object}&quot;">​</a></h2><p>Lua错误对象不是字符串怎么办？先判断实际类型，再选择报告策略，不对任意对象直接 <code>%s</code>。Lua 抛出的值可以不是字符串；C 调用 <code>lua_error</code> 会使用栈顶值作为错误对象，pcall 不保证把它变成文本。本例对字符串使用长度输出，对其他类型固定输出 non-string error object，避免错误处理再次执行对象元方法。</p><p>若需要 traceback，应在 pcall 前放置消息处理器，并把其普通栈索引传给 msgh，处理器在栈展开前调用 <code>luaL_traceback</code>。处理器自身可能失败，因此还要处理 LUA_ERRERR；内存错误等情形不能承诺获得完整堆栈。不要在 pcall 返回后再试图恢复已经展开的原调用链。</p><p>本例 msgh=0，没有生成 traceback；日志保留阶段、退出码和原错误字节。日志若需要持久存储，必须在 lua_close 前复制所需数据，并约定长度与编码，避免泄漏脚本路径或打印二进制字节影响日志协议。这里的 fwrite 只是演示正确字节长度，不是完整结构化日志系统。</p><h2 id="stack-leak" tabindex="-1">栈失衡与引用泄漏 <a class="header-anchor" href="#stack-leak" aria-label="Permalink to &quot;栈失衡与引用泄漏 {#stack-leak}&quot;">​</a></h2><p>Lua宿主循环调用后内存增长怎么查？分别检查栈顶和 registry 引用，清栈不能解除 registry 引用。记录每轮入口与出口 top，检查错误分支是否只留下一个错误对象并及时消耗；再记录每轮成功 ref 与 unref 的数量及对应状态。字符串、函数和 userdata 可因引用仍在而持续可达，强制 GC 无法回收强引用对象。</p><p>不要把 <code>lua_gettop</code> 恒定解释为“没有泄漏”。registry、全局表、闭包 upvalue 和外部 C 分配都不等于栈值数量。也不要用反复 lua_settop(0) 隐藏协议错误，它可能删掉调用者的值。本例只在 main 的最外层清零，因为这一层拥有整个状态，且没有 to-be-closed 栈槽。</p><p>一次性状态退出时统一 lua_close 能回收其 Lua 对象，但长期宿主需要在替换回调时先建立新引用、完成校验，再按明确顺序替换旧引用并 unref，失败保留旧版本或显式拒绝切换。引用数字可复用，日志中应同时记录状态或请求归属，不能只凭 ref 整数关联对象。</p><h2 id="link" tabindex="-1">版本、ABI 与库路径 <a class="header-anchor" href="#link" aria-label="Permalink to &quot;版本、ABI 与库路径 {#link}&quot;">​</a></h2><p>Lua宿主链接失败或启动崩溃先查什么？先核对头文件、库文件和运行时装载路径，再看架构和数值配置。undefined reference 或 unresolved external 通常发生在链接层，不是 Lua chunk 语法错误；找不到 DLL/共享库发生在装载层，也不会被 lua_pcall 捕获。</p><p>本例固定 5.4.9；CMake 成功找到一个路径，仍应审阅它实际选择的开发库，避免系统旧库优先。Windows 导入库与 DLL 要对应，静态链接还要包含所需平台库；Linux/macOS 的运行时查找策略与 Windows 不同。不能把把头文件复制到项目目录当成依赖配置完成。</p><p>如果不同模块共享一个状态，它们必须使用兼容 Lua ABI 与构建配置；跨模块 malloc/free 或运行库边界也需要清楚的释放协议。本文没有构建任何平台二进制，所以没有对具体链接错误作实测结论。</p><h2 id="memory" tabindex="-1">内存统计与资源上限 <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;内存统计与资源上限 {#memory}&quot;">​</a></h2><p>Lua GC能限制整个宿主内存吗？不能。GC 处理 Lua 管理对象的可达性，既不是固定内存预算，也不覆盖任意 C 外部分配和进程开销。可达的大表不会因触发 GC 就变成垃圾；进程 RSS 也不等于 Lua 内存统计值。</p><p>自定义 allocator 可以追踪 Lua 向它请求的块，但必须遵守 lua_Alloc 的分配/重分配/释放契约，区分 osize 的含义、失败时原块仍有效以及新大小为零的释放；计数运算本身也要防止溢出。不能随意依赖 osize 直接加减而不核对回调语义。工程使用默认 allocator，没有实现字节配额，故不宣称内存上限。</p><p>CPU 预算同样独立：关闭标准库并不阻止死循环，指令 hook 也不能覆盖任意长期阻塞 C 回调。生产策略应按威胁模型选择进程超时、内存限制、允许能力和回收方法。本课程只覆盖可信同步插件的接口正确性，未实现安全执行恶意脚本。</p><h2 id="exercise" tabindex="-1">练习 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习 {#exercise}&quot;">​</a></h2><ol><li>top 每次相等，但每轮 luaL_ref 后从不 unref，强制 GC 会解决吗？</li><li>插件报错后有状态变更，为什么 pcall 不能替你回滚？</li><li>Lua 库找不到导致进程无法启动，应修改插件代码还是先查装载配置？</li></ol><h2 id="answers" tabindex="-1">参考解答 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答 {#answers}&quot;">​</a></h2><ol><li>不会。registry 强引用使对象仍可达；应按请求/回调归属解除引用，避免为诊断随意清空整个 registry。</li><li>pcall 只改变控制流与返回状态，不记录业务写入日志；需要宿主显式快照、暂存后提交或销毁独立请求状态。</li><li>先查装载路径、架构与库版本，错误发生在任何 Lua 代码执行之前；pcall 无法捕获操作系统装载失败。</li></ol><p>依据：<a href="https://www.lua.org/manual/5.4/manual.html#4.4" target="_blank" rel="noopener noreferrer">Lua 5.4 错误处理</a>、<a href="https://www.lua.org/manual/5.4/manual.html#lua_Alloc" target="_blank" rel="noopener noreferrer">内存分配器</a>、<a href="https://www.lua.org/manual/5.4/manual.html#luaL_ref" target="_blank" rel="noopener noreferrer">引用辅助 API</a>，核对 2026-10-17。理论与源码审阅不能替代实际构建、压力测试或分配失败注入。</p>',27)])])}const g=e(o,[["render",i]]);export{h as __pageData,g as default};
